// HC-SR04 Ultrasonic Sensor Distance Measurement
// Wiring: TRIG -> Pin 2, ECHO -> Pin 3, VCC -> 5V, GND -> GND

const int trigPin = 2;
const int echoPin = 3;

void setup() {
  Serial.begin(9600); // Initialize serial communication
  pinMode(trigPin, OUTPUT); // Set TRIG pin as output
  pinMode(echoPin, INPUT);  // Set ECHO pin as input
}

void loop() {
  long duration, distance;

  // Send a 10us HIGH pulse to TRIG pin
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echo pin and calculate duration
  duration = pulseIn(echoPin, HIGH);

  // Calculate distance in centimeters
  // Speed of sound = 340 m/s = 0.034 cm/us
  // Distance = (duration / 2) * 0.034
  distance = (duration / 2) * 0.034;

  // Output distance to Serial Monitor
  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  delay(100); // Wait 100ms before next reading
}

